#!/usr/bin/env bash
# Statically recompiles an N64 (libdragon) ELF into C with N64Recomp, and prepares what our runtime
# needs next to the generated code:
#   <out>/funcs_*.c, funcs.h, recomp_overlays.inl   generated by N64Recomp
#   <out>/<name>.bin                                 the program's memory image (from 0x80000000)
#   <out>/ignored_stubs.c                            weak fallbacks for functions excluded in the .toml
#   <out>/n64_image.h                                addresses the runtime needs (_gp, end of bss, ...)
#   build/n64/include/recomp.h                       N64Recomp's runtime header, made 32-bit safe
#
#   tools/n64-recomp.sh n64/recomp/helloworld.toml
#
# SPDX-FileCopyrightText: 2026 Mitul Shah
# SPDX-License-Identifier: MIT
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
TOML="$(cd "$(dirname "$1")" && pwd)/$(basename "$1")"
RECOMP="$ROOT/build/host-n64recomp/N64Recomp"
TC="${N64_INST:-$HOME/n64-toolchain}/bin"
[[ -x "$RECOMP" ]] || "$ROOT/tools/n64-tools.sh"

TOML_DIR="$(dirname "$TOML")"
val() { sed -n "s/^$1 *= *\"\(.*\)\"/\1/p" "$TOML" | head -1; }
ELF="$TOML_DIR/$(val elf_path)"
OUT="$TOML_DIR/$(val output_func_path)"
[[ -f "$ELF" ]] || { echo "ELF not found: $ELF (build it with tools/n64-libdragon.sh)" >&2; exit 1; }

rm -rf "$OUT" && mkdir -p "$OUT"
(cd "$TOML_DIR" && "$RECOMP" "$TOML" | grep -v '^\[Info\]' || true)
ls "$OUT"/funcs_0.c >/dev/null

# Memory image: every loadable section, laid out from the lowest address (normally 0x80000000).
NAME="$(basename "$ELF" .elf)"
"$TC/mips64-elf-objcopy" -O binary "$ELF" "$OUT/$NAME.bin"
sym() { "$TC/mips64-elf-nm" "$ELF" | awk -v s="$1" '$3 == s { print "0x" $1; exit }'; }
LOW=$("$TC/mips64-elf-readelf" -S -W "$ELF" | awk '$0 ~ /\] / && $0 ~ / A/ { for (i=1;i<=NF;i++) if ($i ~ /^8[0-9a-f]{7}$/) { print "0x" $i; exit } }')
GP=$(sym _gp); END=$(sym end)
cat > "$OUT/n64_image.h" <<EOF
/* Generated by tools/n64-recomp.sh from $(basename "$ELF"). Do not edit. */
#pragma once
#define N64_IMAGE_NAME "$(basename "$ELF" .elf)"
#define N64_IMAGE_VRAM ${LOW}u   /* $NAME.bin starts here */
#define N64_GP         ${GP}u    /* \$gp (_gp) */
#define N64_BSS_END    ${END}u   /* end of .bss; the heap starts here */
EOF

# Weak fallbacks for every function the .toml excludes; HLE implementations override them.
python3 -I - "$TOML" "$OUT/ignored_stubs.c" <<'PY'
import re, sys
toml = open(sys.argv[1]).read()
m = re.search(r'ignored\s*=\s*\[(.*?)\]', toml, re.S)
names = re.findall(r'"([A-Za-z_][A-Za-z0-9_]*)"', m.group(1)) if m else []
with open(sys.argv[2], "w") as f:
    f.write("/* Generated by tools/n64-recomp.sh. Do not edit. */\n#include \"recomp.h\"\n")
    f.write("void n64rt_unimplemented(const char* name, recomp_context* ctx);\n")
    for n in names:
        f.write(f"__attribute__((weak)) void {n}(uint8_t* rdram, recomp_context* ctx) {{ (void)rdram; n64rt_unimplemented(\"{n}\", ctx); }}\n")
# N64Recomp leaves excluded functions out of funcs.h, but generated code still calls them.
import os
fh = os.path.join(os.path.dirname(sys.argv[2]), "funcs.h")
h = open(fh).read()
decls = "".join(f"void {n}(uint8_t* rdram, recomp_context* ctx);\n" for n in names)
anchor = 'extern "C" {\n#endif\n'
assert anchor in h
h = h.replace(anchor, anchor + "/* excluded from recompilation (HLE or stubs), see the .toml */\n" + decls, 1)
open(fh, "w").write(h)
PY

# recomp.h: N64Recomp's header (MIT, Wiseguy), plus a portable 64x64->128 multiply for targets
# without __int128 (32-bit ARM), and declarations for our generic cop0 hooks.
mkdir -p "$ROOT/build/n64/include"
python3 -I - "$ROOT/third_party/_src/N64Recomp-598ce20/include/recomp.h" "$ROOT/build/n64/include/recomp.h" <<'PY'
import sys
s = open(sys.argv[1]).read()
portable = '''#else
/* firetv-native: portable 64x64->128 multiply for targets without __int128 (e.g. armv7). */
static inline void DMULTU(uint64_t a, uint64_t b, uint64_t* lo64, uint64_t* hi64) {
    const uint64_t a_lo = (uint32_t)a, a_hi = a >> 32, b_lo = (uint32_t)b, b_hi = b >> 32;
    const uint64_t p0 = a_lo * b_lo, p1 = a_lo * b_hi, p2 = a_hi * b_lo, p3 = a_hi * b_hi;
    const uint64_t mid = (p0 >> 32) + (uint32_t)p1 + (uint32_t)p2;
    *lo64 = (mid << 32) | (uint32_t)p0;
    *hi64 = p3 + (p1 >> 32) + (p2 >> 32) + (mid >> 32);
}
static inline void DMULT(int64_t a, int64_t b, int64_t* lo64, int64_t* hi64) {
    uint64_t lo, hi;
    DMULTU((uint64_t)a, (uint64_t)b, &lo, &hi);
    if (a < 0) hi -= (uint64_t)b;
    if (b < 0) hi -= (uint64_t)a;
    *lo64 = (int64_t)lo;
    *hi64 = (int64_t)hi;
}
#endif'''
old = '#else\n#error "128-bit integer type not found"\n#endif'
assert old in s, "recomp.h changed"
s = s.replace(old, portable, 1)
memwu = '#define MEM_W(offset, reg) \\\n'
assert memwu in s
s = s.replace(memwu, '/* firetv-native: lwu (used by the generator, missing from this header) */\n'
              '#define MEM_WU(offset, reg) \\\n    (*(uint32_t*)(rdram + ((((reg) + (offset))) - 0xFFFFFFFF80000000)))\n\n' + memwu, 1)
decl = 'void do_break(uint32_t vram);\n'
assert decl in s
s = s.replace(decl, decl + '/* firetv-native: generic cop0 access (see tools/n64-tools.sh) */\n'
              'gpr cop0_read(recomp_context* ctx, int reg);\nvoid cop0_write(recomp_context* ctx, int reg, gpr value);\n'
              '/* firetv-native: called by functions N64Recomp could not translate (see tools/n64-tools.sh) */\n'
              'void n64rt_unrecompilable(const char* name, recomp_context* ctx);\n', 1)
open(sys.argv[2], 'w').write("/* Generated from N64Recomp's include/recomp.h (MIT, (c) 2024 Wiseguy) by tools/n64-recomp.sh */\n" + s)
PY
echo "recompiled $(grep -c '^RECOMP_FUNC' "$OUT"/funcs_*.c | awk -F: '{s+=$2} END {print s}') functions -> $OUT"
cat "$OUT/n64_image.h" | grep define
